-- Mr. Fluent Kids curriculum expansion: K1-K5 and Primary 3-6.
-- This seed is safe to rerun. Existing published rows are never overwritten.
-- New content remains unpublished for academy/teacher review before paid access.
-- Kids monthly subscription price follows the existing platform rate: EGP 100 / 30 days.
update public.mrfluent_kids_tracks
set price_egp = 100, duration_days = 30, updated_at = now()
where code in ('START_ZERO','PRIMARY_SUPPORT');

with unit_data(level_code, sort_order, title, description) as (
 values
 ('K1',1,'Unit 1: Meet A–F','Recognise the first six letters and hear their common sounds.'),
 ('P34',1,'Unit 1: School and Community','Expand vocabulary for school, places and everyday activities.'),
 ('K1',2,'Unit 2: Meet G–L','Practise letter shapes, names and first sounds from G to L.'),
 ('P34',2,'Unit 2: Present Simple','Use present simple for routines and facts.'),
 ('K1',3,'Unit 3: Meet M–R','Build confidence with letter families and sound matching.'),
 ('P34',3,'Unit 3: Questions and Prepositions','Ask about people, time and place; describe simple positions.'),
 ('K1',4,'Unit 4: Meet S–Z','Review the remaining letters and celebrate alphabet progress.'),
 ('P34',4,'Unit 4: Read and Write','Read short paragraphs and write connected sentences.'),
 ('P56',1,'Unit 1: Reading Detective','Find the main idea, key details and evidence in a passage.'),
 ('K2',1,'Unit 1: Short A','Blend simple consonant-vowel-consonant words with the short a sound.'),
 ('P56',2,'Unit 2: Grammar in Time','Compare present, past and future forms in familiar situations.'),
 ('K2',2,'Unit 2: Short I','Read and build simple words using the short i sound.'),
 ('K2',3,'Unit 3: Short O','Blend short-o words and listen for the middle sound.'),
 ('P56',3,'Unit 3: Connect Ideas','Use conjunctions and reference words to make writing flow.'),
 ('P56',4,'Unit 4: Plan a Paragraph','Organise a paragraph with a topic sentence and supporting details.'),
 ('K2',4,'Unit 4: Short E and U','Compare short e and short u in simple words.'),
 ('K3',1,'Unit 1: SH and CH','Read common two-letter sound teams at the beginning of words.'),
 ('K3',2,'Unit 2: EE and EA','Explore common long-e spellings in short words.'),
 ('K3',3,'Unit 3: OA, AI and IGH','Notice common vowel teams in high-frequency words.'),
 ('K3',4,'Unit 4: CK, NG and TH','Practise more sound teams and review phonics patterns.'),
 ('K4',1,'Unit 1: Who Does What?','Build short sentences with a subject and an action.'),
 ('K4',2,'Unit 2: Pronouns and Be','Use I, you, he, she and they with am, is and are.'),
 ('K4',3,'Unit 3: Marks and Questions','Use capital letters, full stops and question marks.'),
 ('K4',4,'Unit 4: Questions and Answers','Ask simple questions and answer using complete sentences.'),
 ('K5',1,'Unit 1: Characters and Places','Identify who is in a story and where it happens.'),
 ('K5',2,'Unit 2: Story Order','Retell simple events using first, next and finally.'),
 ('K5',3,'Unit 3: Story Talk','Practise dialogue, feelings and polite expressions.'),
 ('K5',4,'Unit 4: Make a Mini Story','Create a beginning, a problem and a clear ending.')
)
insert into public.mrfluent_kids_units(level_id,title,description,sort_order,is_published)
select l.id,u.title,u.description,u.sort_order,false
from unit_data u join public.mrfluent_kids_levels l on l.code=u.level_code
on conflict(level_id,sort_order) do update
set title=excluded.title,description=excluded.description,updated_at=now()
where public.mrfluent_kids_units.is_published=false;

with lesson_data(level_code,unit_sort,lesson_sort,title,objective,lesson_type,lesson_payload) as (
 values
 ('K1',1,1,'Meet A, B and C','Recognise A, B and C and connect each letter with a familiar word.','learn','{"intro":"Letter names and letter sounds are different. Meet A in apple, B in ball, and C in cat.","steps":["Look at A a and say apple.","Look at B b and say ball.","Look at C c and say cat."],"audio_words":["apple","ball","cat"],"translations":{"cat":"قطة","ball":"كرة","apple":"تفاحة"}}'::jsonb),
 ('P34',1,1,'Around My School','Name common places and objects around school.','learn','{"intro":"School has places for learning, playing and reading.","steps":["Read the place names.","Match each place to what happens there.","Use one word in a sentence."],"audio_words":["library","playground","classroom"],"translations":{"library":"مكتبة","classroom":"فصل دراسي","playground":"ملعب"}}'::jsonb),
 ('P34',1,2,'Daily Activities','Talk about familiar daily routines with verbs.','learn','{"intro":"We use action verbs to describe our day.","steps":["Read wake up, eat and study.","Put the activities in your usual order.","Say one true sentence about your day."],"audio_words":["wake up","eat","study"],"translations":{"eat":"يأكل","study":"يذاكر","wake up":"يستيقظ"}}'::jsonb),
 ('K1',1,2,'Meet D, E and F','Recognise D, E and F in familiar words.','learn','{"intro":"Meet D in dog, E in egg, and F in fish. Say each word slowly.","steps":["Trace D d with a finger.","Say egg and listen to its first sound.","Find F f in fish."],"audio_words":["dog","egg","fish"],"translations":{"dog":"كلب","egg":"بيضة","fish":"سمكة"}}'::jsonb),
 ('P34',1,3,'Choose the Place','Match an activity to a suitable place.','game','{"intro":"Think about where each activity normally happens.","steps":["Read the activity.","Think of the most suitable place.","Choose the best answer."],"options":[{"label":"library","translation":"مكتبة"},{"label":"kitchen","translation":"مطبخ"},{"label":"bedroom","translation":"غرفة نوم"}],"question":"Where do you borrow books?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K1',1,3,'Letter Sound Match','Choose the letter that begins a familiar word.','game','{"intro":"Listen to the word before you choose its first letter.","steps":["Say the word ball.","Listen for the first sound.","Choose the letter B."],"options":[{"label":"A","translation":"حرف A"},{"label":"B","translation":"حرف B"},{"label":"S","translation":"حرف S"}],"question":"Which letter begins ball?","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('K1',2,1,'Goat, Hat and Igloo','Connect G, H and I with familiar picture words.','learn','{"intro":"G starts goat, H starts hat, and I starts igloo.","steps":["Say goat and notice /g/.","Say hat and notice /h/.","Say igloo and notice /i/."],"audio_words":["goat","hat","igloo"],"translations":{"hat":"قبعة","goat":"ماعز","igloo":"بيت جليدي"}}'::jsonb),
 ('P34',2,1,'My Daily Routine','Use present simple to describe repeated activities.','learn','{"intro":"Use the present simple for routines: I walk to school and I study English.","steps":["Find the subject.","Choose the present-tense verb.","Say one sentence about your routine."],"audio_words":["usually","every day","routine"],"translations":{"routine":"روتين","usually":"عادةً","every day":"كل يوم"}}'::jsonb),
 ('K1',2,2,'J, K and L','Recognise J, K and L in short spoken words.','learn','{"intro":"Meet J in jam, K in kite, and L in lion.","steps":["Point to J j and say jam.","Point to K k and say kite.","Point to L l and say lion."],"audio_words":["jam","kite","lion"],"translations":{"jam":"مربى","kite":"طائرة ورقية","lion":"أسد"}}'::jsonb),
 ('P34',2,2,'He or She Does','Recognise the s ending with he or she in present simple.','learn','{"intro":"For many present-simple verbs, he and she take an s ending.","steps":["Compare I play and She plays.","Read He reads.","Choose the verb that matches the subject."],"audio_words":["play","plays","reads"],"translations":{"play":"يلعب","plays":"يلعب","reads":"يقرأ"}}'::jsonb),
 ('P34',2,3,'Complete the Routine','Choose a present-simple verb form.','game','{"intro":"Check the subject before you choose the verb.","steps":["Read the whole sentence.","Find the subject.","Choose the correct verb form."],"options":[{"label":"study","translation":"يذاكر"},{"label":"studies","translation":"تذاكر"},{"label":"studying","translation":"يذاكر الآن"}],"question":"She ___ English every day.","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('K1',2,3,'Find the First Sound','Match a word''s first sound to its letter.','game','{"intro":"Listen carefully, then find the letter you hear at the start.","steps":["Say hat slowly.","Stretch the first sound /h/.","Choose H."],"options":[{"label":"G","translation":"حرف G"},{"label":"H","translation":"حرف H"},{"label":"L","translation":"حرف L"}],"question":"Which letter begins hat?","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('K1',3,1,'M, N and O','Recognise M, N and O and their example words.','learn','{"intro":"M starts moon, N starts nest, and O starts octopus.","steps":["Say moon and hum /m/.","Say nest and notice /n/.","Say octopus and notice the first sound."],"audio_words":["moon","nest","octopus"],"translations":{"moon":"قمر","nest":"عش","octopus":"أخطبوط"}}'::jsonb),
 ('P34',3,1,'Who, When and Where','Choose question words for people, time and places.','learn','{"intro":"Who asks about a person, when asks about time, and where asks about a place.","steps":["Read the question.","Decide which information is needed.","Choose the question word."],"audio_words":["who","when","where"],"translations":{"who":"من","when":"متى","where":"أين"}}'::jsonb),
 ('P34',3,2,'In, On and Under','Describe where an object is using common prepositions.','learn','{"intro":"Prepositions explain where something is: in the bag, on the desk, under the chair.","steps":["Look at the object and place.","Choose in, on or under.","Say the whole phrase."],"audio_words":["in","on","under"],"translations":{"in":"داخل","on":"على","under":"تحت"}}'::jsonb),
 ('K1',3,2,'P, Q and R','Recognise P, Q and R through familiar words.','learn','{"intro":"P starts pen, Q starts queen, and R starts rabbit.","steps":["Find P in pen.","Say queen and point to Q.","Say rabbit and find R."],"audio_words":["pen","queen","rabbit"],"translations":{"pen":"قلم","queen":"ملكة","rabbit":"أرنب"}}'::jsonb),
 ('K1',3,3,'Rabbit Starts With…','Select the initial letter in a spoken word.','game','{"intro":"Say rabbit aloud and listen to its beginning sound.","steps":["Say rabbit slowly.","Listen for /r/.","Choose R."],"options":[{"label":"P","translation":"حرف P"},{"label":"Q","translation":"حرف Q"},{"label":"R","translation":"حرف R"}],"question":"Which letter begins rabbit?","audio_words":[],"translations":{},"correct_index":2}'::jsonb),
 ('P34',3,3,'Find the Right Preposition','Choose a preposition that describes a position.','game','{"intro":"Picture the object before you choose the word.","steps":["Read the sentence.","Imagine the position.","Choose the matching preposition."],"options":[{"label":"on","translation":"على"},{"label":"under","translation":"تحت"},{"label":"between","translation":"بين"}],"question":"The book is ___ the desk.","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K1',4,1,'S, T and U','Recognise S, T and U in simple words.','learn','{"intro":"S starts sun, T starts tree, and U starts umbrella.","steps":["Make the /s/ sound in sun.","Tap T in tree.","Say umbrella and find U."],"audio_words":["sun","tree","umbrella"],"translations":{"sun":"شمس","tree":"شجرة","umbrella":"مظلة"}}'::jsonb),
 ('P34',4,1,'Find the Main Idea','Identify what a short paragraph is mostly about.','learn','{"intro":"The main idea tells what the paragraph is mostly about.","steps":["Read the paragraph once.","Notice the repeated topic.","Say the main idea in your own words."],"audio_words":["main idea","detail","paragraph"],"translations":{"detail":"تفصيل","main idea":"الفكرة الرئيسية","paragraph":"فقرة"}}'::jsonb),
 ('P34',4,2,'Connect Two Sentences','Use and, but or because to join simple ideas.','learn','{"intro":"Connectors help ideas fit together: and adds, but contrasts, because gives a reason.","steps":["Read the two ideas.","Choose the relationship between them.","Join the ideas with a connector."],"audio_words":["and","but","because"],"translations":{"and":"و","but":"لكن","because":"لأن"}}'::jsonb),
 ('K1',4,2,'V, W, X, Y and Z','Become familiar with the final letters of the alphabet.','learn','{"intro":"Meet V in van, W in web, X in box, Y in yak, and Z in zebra.","steps":["Say van and point to V.","Find W in web.","Find X, Y and Z in the alphabet."],"audio_words":["van","web","box","zebra"],"translations":{"box":"صندوق","van":"شاحنة صغيرة","web":"شبكة","zebra":"حمار وحشي"}}'::jsonb),
 ('P34',4,3,'Choose the Connector','Select a connector that matches the meaning.','game','{"intro":"Read both parts to understand their relationship.","steps":["Read the first idea.","Read the second idea.","Choose a connector that makes sense."],"options":[{"label":"but","translation":"لكن"},{"label":"because","translation":"لأن"},{"label":"or","translation":"أو"}],"question":"I was tired, ___ I finished my homework.","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K1',4,3,'Alphabet Treasure Hunt','Review letter recognition and first sounds.','game','{"intro":"You found many letters. Match each word with its first letter.","steps":["Say sun, ball and fish.","Listen for each first sound.","Choose the matching letter."],"options":[{"label":"M","translation":"حرف M"},{"label":"S","translation":"حرف S"},{"label":"B","translation":"حرف B"}],"question":"Which letter begins sun?","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('P56',1,1,'Topic and Main Idea','Distinguish a text''s topic from its main idea.','learn','{"intro":"The topic tells what a text is about. The main idea says what the writer tells us about that topic.","steps":["Name the topic in a few words.","Read the whole paragraph.","State the main idea in one sentence."],"audio_words":["topic","main idea","writer"],"translations":{"topic":"موضوع","writer":"كاتب","main idea":"الفكرة الرئيسية"}}'::jsonb),
 ('K2',1,1,'Blend C–A–T','Blend three letter sounds to read cat.','learn','{"intro":"Touch each sound, then slide them together: /c/ /a/ /t/ — cat.","steps":["Say /c/.","Say short /a/.","Blend /c/ /a/ /t/ into cat."],"audio_words":["cat","mat","map"],"translations":{"cat":"قطة","map":"خريطة","mat":"حصيرة"}}'::jsonb),
 ('P56',1,2,'Find Text Evidence','Point to a sentence that supports an answer.','learn','{"intro":"Good readers return to the text to check their answers.","steps":["Read the question.","Find the part that gives a clue.","Use the words in the text as evidence."],"audio_words":["evidence","clue","sentence"],"translations":{"clue":"دليل صغير","evidence":"دليل","sentence":"جملة"}}'::jsonb),
 ('K2',1,2,'Tap the Sounds','Hear the three sounds in a short-a word.','learn','{"intro":"A short word can have three sounds. Move slowly from left to right.","steps":["Tap once for each sound in map.","Blend the sounds together.","Read the whole word."],"audio_words":["map","tap","bag"],"translations":{"bag":"حقيبة","map":"خريطة","tap":"ينقر"}}'::jsonb),
 ('K2',1,3,'Short A Word Choice','Choose a word with the short a sound.','game','{"intro":"Listen for the short a sound in the middle of the word.","steps":["Say each option aloud.","Listen to the middle vowel.","Choose the word with short a."],"options":[{"label":"cat","translation":"قطة"},{"label":"cup","translation":"كوب"},{"label":"dog","translation":"كلب"}],"question":"Which word has the short a sound?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('P56',1,3,'Main Idea or Detail?','Identify whether a statement is broad or specific.','game','{"intro":"A main idea covers the whole paragraph. A detail supports it.","steps":["Read the statement.","Ask whether it covers the whole text.","Choose main idea or detail."],"options":[{"label":"detail","translation":"تفصيل"},{"label":"main idea","translation":"فكرة رئيسية"},{"label":"title only","translation":"عنوان فقط"}],"question":"A fact about one character is usually a…","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('P56',2,1,'Present and Past','Recognise present and past forms in simple sentences.','learn','{"intro":"Present tells what happens now or usually. Past tells what already happened.","steps":["Compare I play and I played.","Look for time words.","Choose the tense that matches the time."],"audio_words":["today","yesterday","usually"],"translations":{"today":"اليوم","usually":"عادةً","yesterday":"أمس"}}'::jsonb),
 ('K2',2,1,'Build S–I–T','Blend s, i and t to read sit.','learn','{"intro":"Blend the sounds without adding an extra vowel: /s/ /i/ /t/ — sit.","steps":["Say /s/.","Say short /i/.","Blend the sounds to read sit."],"audio_words":["sit","pin","pig"],"translations":{"pig":"خنزير","pin":"دبوس","sit":"يجلس"}}'::jsonb),
 ('P56',2,2,'Talk About the Future','Use going to for a simple plan.','learn','{"intro":"We can use am, is or are going to plus a verb to talk about a plan.","steps":["Choose who is doing the action.","Use the correct form of be.","Add going to and the action."],"audio_words":["plan","tomorrow","visit"],"translations":{"plan":"خطة","visit":"يزور","tomorrow":"غدًا"}}'::jsonb),
 ('K2',2,2,'Change One Sound','Notice how one sound can change a word.','learn','{"intro":"Change one letter and listen: sit, sip, and six.","steps":["Read sit.","Change the last sound to make sip.","Compare the words."],"audio_words":["sit","sip","six"],"translations":{"sip":"يرتشف","sit":"يجلس","six":"ستة"}}'::jsonb),
 ('K2',2,3,'Find Short I','Identify a word with a short i sound.','game','{"intro":"The vowel i can make a short sound, as in pin.","steps":["Say the options.","Listen for short i.","Choose pin."],"options":[{"label":"pin","translation":"دبوس"},{"label":"pan","translation":"مقلاة"},{"label":"pet","translation":"حيوان أليف"}],"question":"Which word has short i?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('P56',2,3,'Choose the Time Form','Pick a verb form that matches the time clue.','game','{"intro":"The time word helps you choose the correct verb form.","steps":["Find the time word.","Identify past, present or future.","Choose the sentence that matches."],"options":[{"label":"read","translation":"قرأنا"},{"label":"will read","translation":"سنقرأ"},{"label":"are reading","translation":"نقرأ الآن"}],"question":"Yesterday, we ___ a story.","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K2',3,1,'Blend D–O–G','Blend sounds to read dog.','learn','{"intro":"Put the sounds together: /d/ /o/ /g/ — dog.","steps":["Say /d/.","Say short /o/.","Blend to read dog."],"audio_words":["dog","hop","box"],"translations":{"box":"صندوق","dog":"كلب","hop":"يقفز"}}'::jsonb),
 ('P56',3,1,'Because and So','Use because for a reason and so for a result.','learn','{"intro":"Because introduces a reason. So introduces a result.","steps":["Find the reason.","Find the result.","Join them with the matching connector."],"audio_words":["reason","result","because"],"translations":{"reason":"سبب","result":"نتيجة","because":"لأن"}}'::jsonb),
 ('K2',3,2,'Word Families: -op','Read words that share the -op ending.','learn','{"intro":"The ending stays the same while the first sound changes: hop, top, mop.","steps":["Read hop.","Change h to t and read top.","Change t to m and read mop."],"audio_words":["hop","top","mop"],"translations":{"hop":"يقفز","mop":"ممسحة","top":"أعلى"}}'::jsonb),
 ('P56',3,2,'Although and But','Recognise contrast between two ideas.','learn','{"intro":"But and although can show a contrast between ideas.","steps":["Read both ideas.","Notice the contrast.","Choose a connector with the right meaning."],"audio_words":["although","but","however"],"translations":{"but":"لكن","however":"ومع ذلك","although":"رغم أن"}}'::jsonb),
 ('P56',3,3,'Connect the Ideas','Choose a connector that matches the relationship between ideas.','game','{"intro":"Look for addition, contrast, reason or result.","steps":["Read the complete sentence.","Name the relationship.","Choose a suitable connector."],"options":[{"label":"so","translation":"لذلك"},{"label":"although","translation":"رغم أن"},{"label":"but","translation":"لكن"}],"question":"It was raining, ___ we stayed inside.","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K2',3,3,'Short O Match','Choose a short-o word from picture options.','game','{"intro":"Listen to the vowel sound in the middle.","steps":["Say each word.","Stretch the middle vowel.","Pick the short-o word."],"options":[{"label":"dog","translation":"كلب"},{"label":"dig","translation":"يحفر"},{"label":"duck","translation":"بطة"}],"question":"Which word has short o?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('P56',4,1,'Topic Sentence','Write a clear topic sentence for one paragraph.','learn','{"intro":"A topic sentence tells the reader the main point of the paragraph.","steps":["Choose one topic.","State the main point clearly.","Keep the sentence focused."],"audio_words":["topic sentence","focused","point"],"translations":{"point":"نقطة","focused":"محدد","topic sentence":"جملة الموضوع"}}'::jsonb),
 ('K2',4,1,'Read Bed and Red','Read short-e words with clear middle vowels.','learn','{"intro":"Listen to short e in bed, red, and pen.","steps":["Say bed.","Change the first sound to read red.","Read pen and notice short e."],"audio_words":["bed","red","pen"],"translations":{"bed":"سرير","pen":"قلم","red":"أحمر"}}'::jsonb),
 ('P56',4,2,'Add Supporting Details','Choose details that support one central idea.','learn','{"intro":"Supporting details explain or prove the point of your topic sentence.","steps":["Read the topic sentence.","Choose two relevant details.","Remove details that do not fit."],"audio_words":["support","relevant","detail"],"translations":{"detail":"تفصيل","support":"يدعم","relevant":"مرتبط"}}'::jsonb),
 ('K2',4,2,'Read Sun and Cup','Hear short u in familiar CVC words.','learn','{"intro":"Short u is heard in sun and cup.","steps":["Say sun slowly.","Say cup slowly.","Compare the middle vowel sound."],"audio_words":["sun","cup","bus"],"translations":{"bus":"حافلة","cup":"كوب","sun":"شمس"}}'::jsonb),
 ('K2',4,3,'Vowel Sound Detective','Distinguish short e and short u in simple words.','game','{"intro":"Listen to the middle vowel and choose carefully.","steps":["Say pen and sun.","Hear the difference between e and u.","Choose the word with short u."],"options":[{"label":"bed","translation":"سرير"},{"label":"sun","translation":"شمس"},{"label":"red","translation":"أحمر"}],"question":"Which word has short u?","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('P56',4,3,'Build a Paragraph','Order a topic sentence and supporting details logically.','game','{"intro":"A clear paragraph usually starts with the main point and follows with helpful details.","steps":["Choose the topic sentence.","Place related details after it.","Read the paragraph to check the flow."],"options":[{"label":"Explain the main point","translation":"يوضح الفكرة الرئيسية"},{"label":"Change to a new topic","translation":"ينتقل لموضوع جديد"},{"label":"Repeat unrelated words","translation":"يكرر كلمات غير مرتبطة"}],"question":"What should a supporting detail do?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K3',1,1,'Meet SH','Recognise sh as one sound in common words.','learn','{"intro":"Two letters can work together to make one sound: sh, as in ship and shell.","steps":["Say ship.","Notice sh is one sound.","Read shell and shop."],"audio_words":["ship","shell","shop"],"translations":{"ship":"سفينة","shop":"متجر","shell":"صدفة"}}'::jsonb),
 ('K3',1,2,'Meet CH','Hear and read ch in familiar words.','learn','{"intro":"The letters c and h can work together, as in chip and chin.","steps":["Say chip.","Notice the first sound.","Read chin and much."],"audio_words":["chip","chin","much"],"translations":{"chin":"ذقن","chip":"شريحة","much":"كثير"}}'::jsonb),
 ('K3',1,3,'SH or CH?','Choose the correct beginning sound team.','game','{"intro":"Listen to the beginning of each word.","steps":["Say ship.","Say chip.","Choose the sound team for ship."],"options":[{"label":"sh","translation":"الصوت sh"},{"label":"ch","translation":"الصوت ch"},{"label":"th","translation":"الصوت th"}],"question":"Which sound team starts ship?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K3',2,1,'Long E with EE','Recognise ee in words such as see and feet.','learn','{"intro":"In many familiar words, ee says the long e sound.","steps":["Read see.","Read feet.","Find ee in green."],"audio_words":["see","feet","green"],"translations":{"see":"يرى","feet":"أقدام","green":"أخضر"}}'::jsonb),
 ('K3',2,2,'Long E with EA','Recognise ea as a long-e spelling in common words.','learn','{"intro":"The letters ea can say long e in read and team.","steps":["Read team.","Read clean.","Notice the ea spelling."],"audio_words":["team","clean","read"],"translations":{"read":"يقرأ","team":"فريق","clean":"نظيف"}}'::jsonb),
 ('K3',2,3,'Find the Long E Team','Identify a common long-e spelling.','game','{"intro":"Look for the letters that work together.","steps":["Read each option.","Look for ee.","Choose the word with ee."],"options":[{"label":"feet","translation":"أقدام"},{"label":"ship","translation":"سفينة"},{"label":"cat","translation":"قطة"}],"question":"Which word contains ee?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K3',3,1,'OA in Boat','Read oa as a vowel team in familiar words.','learn','{"intro":"In boat and road, oa often says a long o sound.","steps":["Read boat.","Read road.","Find oa in coat."],"audio_words":["boat","road","coat"],"translations":{"boat":"قارب","coat":"معطف","road":"طريق"}}'::jsonb),
 ('K3',3,2,'AI in Rain','Recognise ai in simple words.','learn','{"intro":"In rain and train, ai often says a long a sound.","steps":["Say rain.","Say train.","Find ai in paint."],"audio_words":["rain","train","paint"],"translations":{"rain":"مطر","paint":"طلاء","train":"قطار"}}'::jsonb),
 ('K3',3,3,'IGH in Night','Recognise igh as a common spelling for the long i sound.','learn','{"intro":"The letter team igh appears in night and light.","steps":["Read night.","Read light.","Notice the letters igh."],"audio_words":["night","light","high"],"translations":{"high":"مرتفع","light":"ضوء","night":"ليل"}}'::jsonb),
 ('K3',4,1,'CK at the End','Recognise ck in short words such as duck and sock.','learn','{"intro":"The letters ck often spell the /k/ sound at the end of a short word.","steps":["Read duck.","Read sock.","Notice ck at the end."],"audio_words":["duck","sock","back"],"translations":{"back":"الخلف","duck":"بطة","sock":"جورب"}}'::jsonb),
 ('K3',4,2,'NG at the End','Hear the ng sound in common words.','learn','{"intro":"The ng ending makes a special sound in song and ring.","steps":["Say song.","Say ring.","Listen for the ending sound."],"audio_words":["song","ring","long"],"translations":{"long":"طويل","ring":"خاتم","song":"أغنية"}}'::jsonb),
 ('K3',4,3,'Sound Team Review','Match a word to the spelling pattern it contains.','game','{"intro":"Look for two or more letters working together.","steps":["Read boat, ship and duck.","Find the spelling pattern in each word.","Choose the pattern in boat."],"options":[{"label":"oa","translation":"الحرفان oa"},{"label":"sh","translation":"الحرفان sh"},{"label":"ck","translation":"الحرفان ck"}],"question":"Which spelling team is in boat?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K4',1,1,'Person and Action','Identify who is in a sentence and what they do.','learn','{"intro":"A simple sentence can tell us who and what happens: The cat sleeps.","steps":["Find the person or animal.","Find the action word.","Say the whole sentence."],"audio_words":["cat","sleeps","runs"],"translations":{"cat":"قطة","runs":"يجري","sleeps":"ينام"}}'::jsonb),
 ('K4',1,2,'Build Three Words','Put a subject, verb and object in a sensible order.','learn','{"intro":"English sentences often follow subject, verb, object order.","steps":["Choose who: I.","Choose an action: like.","Choose a thing: books."],"audio_words":["I","like","books"],"translations":{"I":"أنا","like":"أحب","books":"كتب"}}'::jsonb),
 ('K4',1,3,'Choose the Sentence','Recognise correct basic English word order.','game','{"intro":"Read each sentence aloud and check the word order.","steps":["Read the choices.","Listen for the natural order.","Choose the correct sentence."],"options":[{"label":"I like books.","translation":"أنا أحب الكتب"},{"label":"Like I books.","translation":"أحب أنا كتب"},{"label":"Books I like the.","translation":"كتب أنا أحب الـ"}],"question":"Which sentence is correct?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K4',2,1,'I Am and You Are','Use am and are with the right pronouns.','learn','{"intro":"Say I am ready and You are kind.","steps":["Read I am ready.","Read You are kind.","Notice which verb matches each subject."],"audio_words":["ready","kind","happy"],"translations":{"kind":"لطيف","happy":"سعيد","ready":"مستعد"}}'::jsonb),
 ('K4',2,2,'He Is and She Is','Use is with he and she in short sentences.','learn','{"intro":"We say He is happy and She is ready.","steps":["Read He is happy.","Read She is ready.","Choose a pronoun and make a sentence."],"audio_words":["he","she","is"],"translations":{"he":"هو","is":"يكون","she":"هي"}}'::jsonb),
 ('K4',2,3,'Choose Am, Is or Are','Complete a sentence with the matching verb.','game','{"intro":"The subject helps you choose am, is or are.","steps":["Look at the subject.","Say the sentence aloud.","Choose the verb that matches."],"options":[{"label":"am","translation":"أكون"},{"label":"is","translation":"تكون"},{"label":"are","translation":"يكونون"}],"question":"She ___ happy.","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('K4',3,1,'Start with a Capital','Recognise capital letters at the start of sentences and names.','learn','{"intro":"English sentences begin with a capital letter. Names also begin with a capital.","steps":["Find the first letter.","Check the name.","Rewrite the sentence with a capital."],"audio_words":["Lina","Ali","Monday"],"translations":{"Ali":"علي","Lina":"لينا","Monday":"الاثنين"}}'::jsonb),
 ('K4',3,2,'Stop or Question?','Choose punctuation for a statement or question.','learn','{"intro":"A statement usually ends with a full stop. A question ends with a question mark.","steps":["Read the sentence.","Ask whether it is a question.","Choose the ending mark."],"audio_words":["statement","question","full stop"],"translations":{"question":"سؤال","full stop":"نقطة","statement":"جملة خبرية"}}'::jsonb),
 ('K4',3,3,'Finish the Sentence','Use the question mark for a direct question.','game','{"intro":"Look at what the sentence is doing before choosing a mark.","steps":["Read the words.","Notice that the sentence asks something.","Choose the correct punctuation."],"options":[{"label":".","translation":"نقطة"},{"label":"?","translation":"علامة استفهام"},{"label":"!","translation":"علامة تعجب"}],"question":"What mark ends a question?","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('K4',4,1,'What and Where','Understand what and where in short questions.','learn','{"intro":"What asks about a thing. Where asks about a place.","steps":["Read What is this?","Read Where is the bag?","Match each question to its meaning."],"audio_words":["what","where","place"],"translations":{"what":"ماذا","place":"مكان","where":"أين"}}'::jsonb),
 ('K4',4,2,'Yes or No Answers','Answer simple questions clearly.','learn','{"intro":"A yes-or-no question can begin with is, are, do or does.","steps":["Listen to the question.","Choose yes or no.","Say a full answer when you can."],"audio_words":["yes","no","answer"],"translations":{"no":"لا","yes":"نعم","answer":"إجابة"}}'::jsonb),
 ('K4',4,3,'Match the Question','Choose a question word that fits the information needed.','game','{"intro":"Think about whether you need a thing or a place.","steps":["Read both choices.","Think about the answer you need.","Choose the best question word."],"options":[{"label":"What","translation":"ماذا"},{"label":"Where","translation":"أين"},{"label":"Who","translation":"من"}],"question":"Which word asks about a place?","audio_words":[],"translations":{},"correct_index":1}'::jsonb),
 ('K5',1,1,'Meet the Characters','Name the people or animals in a short story.','learn','{"intro":"A character is a person or an animal in a story.","steps":["Look at the story picture.","Name one character.","Say what the character is doing."],"audio_words":["character","story","animal"],"translations":{"story":"قصة","animal":"حيوان","character":"شخصية"}}'::jsonb),
 ('K5',1,2,'Where Does It Happen?','Identify the setting in a short story.','learn','{"intro":"The setting tells us where and when a story happens.","steps":["Look for place words.","Find where the characters are.","Describe the setting in one sentence."],"audio_words":["setting","forest","home"],"translations":{"home":"منزل","forest":"غابة","setting":"مكان وزمان القصة"}}'::jsonb),
 ('K5',1,3,'Find the Setting','Choose the place described in a short story.','game','{"intro":"Read the clue and look for a place that matches it.","steps":["Listen to the clue.","Picture the place.","Choose the matching setting."],"options":[{"label":"forest","translation":"غابة"},{"label":"classroom","translation":"فصل"},{"label":"kitchen","translation":"مطبخ"}],"question":"Where do trees and woodland animals live?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K5',2,1,'First, Next, Finally','Put three events in chronological order.','learn','{"intro":"Stories often have a beginning, a middle and an ending.","steps":["Find what happens first.","Find the next event.","Tell how the story ends."],"audio_words":["first","next","finally"],"translations":{"next":"بعد ذلك","first":"أولًا","finally":"أخيرًا"}}'::jsonb),
 ('K5',2,2,'Cause and Result','Notice a simple cause and its result.','learn','{"intro":"A story event can happen because of another event.","steps":["Read what happened.","Ask why it happened.","Explain the result."],"audio_words":["because","result","then"],"translations":{"then":"ثم","result":"نتيجة","because":"لأن"}}'::jsonb),
 ('K5',2,3,'Put the Events in Order','Choose the best sequence for a familiar activity.','game','{"intro":"Think about which action must happen before the others.","steps":["Read the three actions.","Imagine doing them.","Choose the sensible order."],"options":[{"label":"Open the book","translation":"افتح الكتاب"},{"label":"Close the book","translation":"أغلق الكتاب"},{"label":"Put it away","translation":"ضعه بعيدًا"}],"question":"What happens first when you read a book?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K5',3,1,'Say It Like a Character','Read a short line as if you were the character.','learn','{"intro":"Characters can speak to each other in a story.","steps":["Read the speaker''s words.","Think about how the character feels.","Say the line clearly."],"audio_words":["hello","please","thank you"],"translations":{"hello":"مرحبًا","please":"من فضلك","thank you":"شكرًا"}}'::jsonb),
 ('K5',3,2,'Feelings in Stories','Recognise feelings from words and actions.','learn','{"intro":"A character might feel happy, worried, surprised or sad.","steps":["Look at the action.","Find clues in the words.","Choose a feeling that fits."],"audio_words":["happy","worried","surprised"],"translations":{"happy":"سعيد","worried":"قلق","surprised":"متفاجئ"}}'::jsonb),
 ('K5',3,3,'Choose a Polite Reply','Select a friendly reply in a simple dialogue.','game','{"intro":"Kind words help characters talk politely.","steps":["Read the short dialogue.","Think about the kind response.","Choose the reply."],"options":[{"label":"You''re welcome.","translation":"العفو"},{"label":"Go away.","translation":"اذهب بعيدًا"},{"label":"I am a desk.","translation":"أنا مكتب"}],"question":"Someone says Thank you. What can you say?","audio_words":[],"translations":{},"correct_index":0}'::jsonb),
 ('K5',4,1,'A Story Beginning','Write or say who and where a story is about.','learn','{"intro":"A beginning can introduce a character and a place.","steps":["Choose a character.","Choose a place.","Say: One day, ..."],"audio_words":["one day","friend","garden"],"translations":{"friend":"صديق","garden":"حديقة","one day":"ذات يوم"}}'::jsonb),
 ('K5',4,2,'A Small Problem','Add a simple problem to a story.','learn','{"intro":"A problem gives the character something to solve.","steps":["Choose something that goes wrong.","Say how the character feels.","Think of a helpful next step."],"audio_words":["problem","lost","help"],"translations":{"help":"مساعدة","lost":"ضائع","problem":"مشكلة"}}'::jsonb),
 ('K5',4,3,'Story Builder','Choose an ending that fits a simple story.','game','{"intro":"A good ending shows how the problem is solved.","steps":["Remember the problem.","Think of a safe helpful solution.","Choose the ending that makes sense."],"options":[{"label":"Ask a trusted adult for help","translation":"اطلب المساعدة من شخص بالغ موثوق"},{"label":"Hide from everyone","translation":"اختبئ من الجميع"},{"label":"Break another book","translation":"أتلف كتابًا آخر"}],"question":"A character loses a book. What is a helpful next step?","audio_words":[],"translations":{},"correct_index":0}'::jsonb)
)
insert into public.mrfluent_kids_lessons(unit_id,title,objective,lesson_type,lesson_payload,sort_order,is_published)
select u.id,d.title,d.objective,d.lesson_type,d.lesson_payload,d.lesson_sort,false
from lesson_data d
join public.mrfluent_kids_levels l on l.code=d.level_code
join public.mrfluent_kids_units u on u.level_id=l.id and u.sort_order=d.unit_sort
on conflict(unit_id,sort_order) do update
set title=excluded.title,objective=excluded.objective,lesson_type=excluded.lesson_type,
    lesson_payload=excluded.lesson_payload,updated_at=now()
where public.mrfluent_kids_lessons.is_published=false;
